message.content:
[
  {
    "sys_fairness_reciprocity": "two hundred for her, same as me.",
    "ce_understood_harm": "hard to picture her walking away with nothing for that.",
    "pda_harm_regret": "I'd carry it around for a long time, like a small meanness",
    "pda_self_consequence_regret": "I'd lose something in how I see myself."
  },
  {
    "sys_fairness_reciprocity": "Equal work, equal thanks.",
    "pda_self_consequence_regret": "whatever trust we had would just be gone, and I'd miss it."
  },
  {
    "sys_fairness_reciprocity": "missed chance to do something plainly fair",
    "pda_self_consequence_regret": "wish I'd been the kind of person who just said yes."
  },
  {
    "sys_fairness_reciprocity": "the work was the same, so the thanks should be too.",
    "pd_personal_consequence_anxiety": "I could lose my standing with people I've worked beside"
  },
  {
    "sys_fairness_reciprocity": "Same hours, same effort, same thank-you.",
    "pda_self_consequence_regret": "I'd hate to lose the easy way we talk now."
  },
  {
    "sys_fairness_reciprocity": "the work was equal, and that's what counts.",
    "pda_self_consequence_regret": "I think I'd end up disappointed in myself for years",
    "pd_personal_consequence_anxiety": "worry the organizer would notice and stop trusting my word."
  },
  {
    "ce_mentalizing_difficulty": "Maybe they had reasons I don't know about.",
    "pda_self_consequence_regret": "giving up something that costs me nothing to keep... I'd mourn that"
  },
  {
    "pda_self_consequence_regret": "I'd miss the version of that evening I have now"
  },
  {
    "pda_self_consequence_regret": "Losing that ease, being unable to look at them straight, would weigh on me."
  },
  {
    "sys_fairness_reciprocity": "Same pay for the same night's work.",
    "pd_personal_consequence_anxiety": "the organizer might trust my judgment less afterward",
    "pda_self_consequence_regret": "Losing someone's good opinion over something this simple would feel awful."
  }
]
